type seed struct{ n int }

func done(s seed) bool     { return s.n == 0 }        // termination
func next(s seed) seed     { return seed{s.n - 1} }   // coalgebra step
func mul(acc uint64, s seed) uint64 { return acc * uint64(s.n) }  // algebra

func Factorial(n int) uint64 {                        // fused, no slice
    acc, s := uint64(1), seed{n}
    for !done(s) {
        acc = mul(acc, s)                             // fold this layer now
        s = next(s)                                   // next seed
    }
    return acc
}

