func Countdown(n int) iter.Seq[int] {                // unfold as an API
    return func(yield func(int) bool) {
        for s := n; s > 0; s-- {
            if !yield(s) { return }               // consumer can stop us
        }
    }
}

func Factorial(n int) uint64 {                        // fused fold
    acc := uint64(1)
    for v := range Countdown(n) { acc *= uint64(v) }  // no slice built
    return acc
}
